#include <iostream>
#include <vector>
using namespace std;

long long count_tilings(int length) {
    const long long modulus = 1000000007;
    vector<long long> ways(length + 1, 0);
    ways[0] = 1;

for (int filled = 1; filled <= length; filled++) {
    ways[filled] = ways[filled - 1];
    if (filled >= 2) {
        ways[filled] += ways[filled - 2];
    }
    ways[filled] %= modulus;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int length;
    cin >> length;
    cout << count_tilings(length) << '\n';
    return 0;
}

